import MiniSearch from 'minisearch';
import { bestAnswer, compareAnswer, entryLevel, info, mentionedProducts, nameTokens, researchText, NEED_HIGH, NEED_MID, NEED_SMALL, specAnswer, type Workload } from './biomiReason';

/**
 * Biomi's "brain": free, in-browser search over the website's own content
 * (public/biomi-index.json, generated by scripts/build-biomi-index.js).
 * No AI and no server calls (except live job openings). It only ever shows
 * information that is on the website, and says so when it can't find an answer.
 */

export type Product = { name: string; brand: string; category: string; description: string; image: string; logo: string; url: string; /** Other categories it is also listed under. */ alsoIn?: string;
	/** Verified specs from content/product-research.md (chatbot only, not shown in modals). */
	research?: { label: string; value: string }[];
	sources?: string[];
	/** e.g. "Not published by Tulip: throughput, size" */
	notPublished?: string;
};
export type Faq = { category: string; q: string; a: string };
export type Office = { name: string; address: string; phone: string; email: string; hours: string };
type Index = { products: Product[]; faqs: Faq[]; offices: Office[]; facts?: { value: string; label: string }[] };

export type Answer = {
	text: string[];
	products?: Product[];
	offices?: Office[];
	jobs?: string[];
	/** Product categories to pick from (catalogue overview). */
	categories?: { name: string; count: number }[];
	/** Side-by-side comparison table (rows x products). */
	compare?: { products: Product[]; rows: { label: string; values: string[] }[] };
	links?: { label: string; href: string }[];
	suggestions?: string[];
	/** Updated conversation memory; when absent the previous memory is kept. */
	context?: BiomiContext;
};

/**
 * What Biomi remembers between messages, so follow-ups like "tell me more
 * about it", "the second one", "show more", "other brands?" or
 * "what about Mindray?" refer back to the previous answer.
 */
export type BiomiContext = {
	/** Product cards in the last answer, in display order. */
	products: Product[];
	/** Every result for the last search (for "show more"). */
	list: Product[];
	/** How many of `list` have been shown so far. */
	shown: number;
	/** The single product being talked about (last referenced or opened). */
	focus?: Product;
	brand?: string;
	category?: string;
	/** The last answer was a company FAQ, not products. */
	faq?: boolean;
};

export const EMPTY_CONTEXT: BiomiContext = { products: [], list: [], shown: 0 };

